package com.indianservers.aichemistryexplorer

private fun classEleven(
    module: String,
    title: String,
    summary: String,
    relationship: String,
    example: String,
    detail: String
): Pair<String, LevelOneConceptContent> = "$module|$title" to LevelOneConceptContent(
    summary = summary,
    explanation = "$detail A board-ready explanation should connect the stated relationship with electronic structure, a measurable trend, a balanced transformation or laboratory evidence, and should name important exceptions instead of treating the rule as absolute.",
    workedExample = "Example: $example Show the governing relationship, apply the stated conditions and finish by interpreting the chemical result.",
    keyRelationship = relationship,
    commonMistake = "Do not answer $title from a memorised trend or name alone. Check the species, physical state, units, reaction conditions and known exceptions before drawing the conclusion.",
    application = "$title supports prediction and problem solving in senior-secondary chemistry, laboratory work, materials, environmental decisions and industrial chemical processes.",
    connections = listOf("Structure-property relationship", "Experimental evidence", "Board-style calculation or equation")
)

internal val seniorSecondaryClassElevenContent: Map<String, LevelOneConceptContent> = mapOf(
    classEleven("Classification and Periodicity: Senior Secondary", "Need and genesis of periodic classification",
        "Periodic classification organises elements so recurring properties can be explained and predicted.",
        "Dobereiner triads -> Newlands octaves -> Mendeleev mass table -> modern atomic-number table",
        "Mendeleev left gaps for undiscovered elements and predicted properties such as those later observed for gallium.",
        "Early schemes used atomic mass and chemical similarity; Moseley's atomic-number evidence resolved mass-order anomalies and established the modern basis."),
    classEleven("Classification and Periodicity: Senior Secondary", "Modern periodic law and long-form table",
        "The physical and chemical properties of elements are periodic functions of atomic number.",
        "period number = highest occupied n; block = differentiating subshell",
        "[Ne]3s2 places magnesium in period 3, s-block and group 2.",
        "The long-form table has seven periods and eighteen groups; position follows valence-shell electronic configuration."),
    classEleven("Classification and Periodicity: Senior Secondary", "Nomenclature of elements above atomic number 100",
        "Temporary systematic element names are built from digit roots until an official IUPAC name and symbol are adopted.",
        "0 nil, 1 un, 2 bi, 3 tri, 4 quad, 5 pent, 6 hex, 7 sept, 8 oct, 9 enn + ium",
        "Atomic number 120 gives un-binilium, Ubn, by joining the roots for 1-2-0.",
        "Each digit is translated in order, the roots are joined, spelling rules are applied and a three-letter temporary symbol is formed."),
    classEleven("Classification and Periodicity: Senior Secondary", "Electronic configurations and s-p-d-f blocks",
        "The differentiating electron places an element in the s, p, d or f block and explains characteristic valence behaviour.",
        "s: ns1-2; p: ns2np1-6; d: (n-1)d1-10ns0-2; f: (n-2)f1-14",
        "Iron, [Ar]3d6 4s2, is a period-4 d-block element.",
        "Aufbau filling, Pauli exclusion and Hund's rule generate configurations, with recognised stability exceptions such as chromium and copper."),
    classEleven("Classification and Periodicity: Senior Secondary", "Atomic and ionic radii trends",
        "Atomic radius generally decreases across a period and increases down a group because effective nuclear charge and shell number change.",
        "cation < parent atom < anion; isoelectronic radius decreases as Z increases",
        "For O2-, F-, Na+ and Mg2+, all have ten electrons; radius decreases in that order as nuclear charge rises.",
        "Covalent, metallic and van der Waals radii are defined differently; ionic size also depends on charge and coordination."),
    classEleven("Classification and Periodicity: Senior Secondary", "Ionization enthalpy trends",
        "Ionization enthalpy is the enthalpy required to remove an electron from an isolated gaseous atom and generally rises across a period.",
        "X(g) -> X+(g) + e-; Delta_iH > 0",
        "Boron has lower first ionization enthalpy than beryllium because a 2p electron is removed more easily than a filled 2s electron.",
        "Nuclear charge, radius, shielding, penetration and half/full-subshell stability explain the trend and its exceptions."),
    classEleven("Classification and Periodicity: Senior Secondary", "Electron-gain enthalpy trends",
        "Electron-gain enthalpy records the enthalpy change when an isolated gaseous atom accepts an electron.",
        "X(g) + e- -> X-(g); more negative value means greater energy release",
        "Chlorine has a more negative value than fluorine because fluorine's compact 2p shell creates stronger incoming-electron repulsion.",
        "Size, effective nuclear charge and stable configurations govern the values; noble gases and filled subshells are important exceptions."),
    classEleven("Classification and Periodicity: Senior Secondary", "Electronegativity, valency and periodic reactivity",
        "Electronegativity generally increases across a period and decreases down a group, shaping bond polarity and chemical reactivity.",
        "DeltaEN predicts bond polarity; main-group valency follows valence-electron requirements",
        "The large electronegativity difference in NaCl favours ionic character, while the smaller difference in HCl gives polar covalent bonding.",
        "Electronegativity is a bonded-atom scale rather than a directly measured isolated-atom enthalpy, and oxidation state may extend beyond simple valency."),

    classEleven("Chemical Bonding and Molecular Structure", "Kossel-Lewis approach",
        "The Kossel-Lewis approach explains bond formation through valence electrons, noble-gas configurations and shared or transferred electron pairs.",
        "ionic: electron transfer; covalent: shared electron pair",
        "Sodium transfers one electron to chlorine to form Na+ and Cl-, whereas two chlorine atoms share a pair in Cl2.",
        "Lewis symbols track valence electrons and distinguish electrovalent attraction from directional covalent bonding."),
    classEleven("Chemical Bonding and Molecular Structure", "Ionic bonding and lattice enthalpy",
        "An ionic solid is a three-dimensional electrostatic lattice whose stability reflects ion charges, sizes and lattice enthalpy.",
        "lattice attraction proportional to |z+z-|/r",
        "MgO has much larger lattice enthalpy than NaCl because its ions carry charges of magnitude two and have strong attraction.",
        "Born-Haber cycles combine formation, atomisation, ionisation, electron-gain and lattice enthalpies using Hess's law."),
    classEleven("Chemical Bonding and Molecular Structure", "Lewis structures and formal charge",
        "Lewis structures distribute valence electrons while formal charge helps select plausible electron arrangements.",
        "FC = valence electrons - nonbonding electrons - one-half bonding electrons",
        "In carbonate, each valid contributor has one C=O and two C-O- bonds; the total charge remains -2.",
        "Count total valence electrons, satisfy terminal atoms, complete the central atom and minimise formal-charge separation where chemically reasonable."),
    classEleven("Chemical Bonding and Molecular Structure", "Resonance structures",
        "Resonance contributors differ only in electron placement; the real molecule is a delocalised hybrid rather than rapidly switching structures.",
        "resonance hybrid energy < energy of any single contributor",
        "The three carbonate C-O bonds are equivalent and intermediate between single and double bonds.",
        "Atomic positions remain fixed between contributors, and equivalent contributors contribute equally to the hybrid."),
    classEleven("Chemical Bonding and Molecular Structure", "Bond length, angle, enthalpy and order",
        "Bond parameters quantify molecular structure and strength; higher bond order usually means shorter, stronger bonding.",
        "bond order increases -> bond length decreases and bond enthalpy generally increases",
        "The C-C, C=C and C triple C bonds become progressively shorter and stronger.",
        "Bond angles depend on geometry and lone-pair repulsion, while bond enthalpy values are often average gas-phase quantities."),
    classEleven("Chemical Bonding and Molecular Structure", "Polarity and dipole moment",
        "Bond dipoles arise from electronegativity differences, but molecular polarity depends on the vector sum of all bond moments.",
        "mu = q x r; molecular dipole = vector sum of bond dipoles",
        "CO2 has polar C=O bonds but zero net dipole because the two equal linear vectors cancel; bent H2O is polar.",
        "Geometry and lone pairs must be considered; polar bonds do not automatically make a polar molecule."),
    classEleven("Chemical Bonding and Molecular Structure", "VSEPR theory",
        "VSEPR theory predicts molecular shape by arranging electron domains to minimise repulsion around the central atom.",
        "lone pair-lone pair > lone pair-bond pair > bond pair-bond pair repulsion",
        "NH3 has four electron domains and tetrahedral electron geometry, but one lone pair gives a trigonal-pyramidal molecular shape.",
        "Multiple bonds count as one domain but repel more strongly, and lone pairs compress adjacent bond angles."),
    classEleven("Chemical Bonding and Molecular Structure", "Valence-bond theory",
        "Valence-bond theory forms covalent bonds by overlap of half-filled atomic orbitals with opposite-spin electron pairing.",
        "head-on overlap -> sigma; side-on overlap -> pi",
        "In N2, one sigma and two pi overlaps create a triple bond.",
        "Overlap magnitude affects strength and directionality, but simple valence-bond theory alone cannot explain every magnetic observation."),
    classEleven("Chemical Bonding and Molecular Structure", "Hybridisation and molecular geometry",
        "Hybridisation mixes atomic orbitals on one atom to create directed, equivalent bonding orbitals consistent with observed geometry.",
        "sp linear; sp2 trigonal planar; sp3 tetrahedral; sp3d trigonal bipyramidal; sp3d2 octahedral",
        "Carbon is sp2 hybridised in ethene: three sigma directions are planar and the unhybridised p orbital forms the pi bond.",
        "Determine steric number from sigma bonds and lone pairs, then distinguish electron-domain geometry from molecular shape."),
    classEleven("Chemical Bonding and Molecular Structure", "Molecular-orbital theory",
        "Molecular orbitals extend over the molecule and form as bonding and antibonding combinations of atomic orbitals.",
        "bond order = (Nb - Na)/2",
        "O2 has two unpaired electrons in pi-star orbitals, bond order two and paramagnetism.",
        "Only atomic orbitals of suitable energy and symmetry combine effectively; electrons fill molecular orbitals by Aufbau, Pauli and Hund rules."),
    classEleven("Chemical Bonding and Molecular Structure", "Homonuclear diatomic molecules",
        "MO configurations explain stability, bond order and magnetism across H2, He2, B2, C2, N2, O2, F2 and Ne2.",
        "bond order > 0 predicts net bonding; unpaired MO electrons give paramagnetism",
        "He2 has equal bonding and antibonding populations, bond order zero, and is not stable as an ordinary molecule.",
        "The 2p orbital energy ordering differs for B2-C2-N2 versus O2-F2 because of s-p mixing."),
    classEleven("Chemical Bonding and Molecular Structure", "Hydrogen bonding",
        "Hydrogen bonding occurs when H bonded to highly electronegative N, O or F interacts with a lone pair on another or the same molecule.",
        "X-H...Y where X,Y commonly N,O,F",
        "Intermolecular hydrogen bonding raises water's boiling point, while intramolecular bonding in o-nitrophenol increases volatility relative to its para isomer.",
        "Distinguish inter- from intramolecular bonding and do not apply the label to every molecule containing hydrogen."),

    classEleven("Hydrocarbons: Senior Secondary", "Hydrocarbon classification and nomenclature",
        "Hydrocarbons are classified as saturated, unsaturated, aliphatic, alicyclic or aromatic and named from parent chain, unsaturation and substituents.",
        "alkane CnH2n+2; alkene CnH2n; alkyne CnH2n-2",
        "CH3CH(CH3)CH2CH3 is 2-methylbutane after selecting the longest chain and lowest locant.",
        "IUPAC naming prioritises the longest chain containing maximum multiple bonds and assigns the lowest valid set of locants."),
    classEleven("Hydrocarbons: Senior Secondary", "Preparation and reactions of alkanes",
        "Alkanes form by hydrogenation, reduction, Wurtz coupling, decarboxylation and Kolbe electrolysis and react mainly by combustion and radical substitution.",
        "RCOONa + NaOH -> RH + Na2CO3; 2RX + 2Na -> R-R + 2NaX",
        "Sodium ethanoate with soda lime gives methane; methane chlorination under UV proceeds through initiation, propagation and termination.",
        "Wurtz coupling is best for symmetrical alkanes, while chlorination often gives mixtures whose proportions reflect hydrogen environments."),
    classEleven("Hydrocarbons: Senior Secondary", "Conformations of ethane",
        "Rotation about the carbon-carbon sigma bond gives conformations with different torsional strain.",
        "staggered energy < eclipsed energy; dihedral angles 60 degrees and 0 degrees",
        "A Newman projection shows staggered ethane at an energy minimum and eclipsed ethane at a maximum.",
        "Conformations interconvert without breaking the sigma bond; they are not constitutional isomers."),
    classEleven("Hydrocarbons: Senior Secondary", "Preparation and reactions of alkenes",
        "Alkenes form by elimination and react by electrophilic addition, oxidation, ozonolysis and polymerisation.",
        "alcohol -> alkene + H2O; alkene + HX follows Markovnikov orientation except HBr/peroxide",
        "Propene plus HBr gives mainly 2-bromopropane, but peroxide changes HBr addition to 1-bromopropane.",
        "Carbocation stability explains normal orientation; ozonolysis products locate the original double bond."),
    classEleven("Hydrocarbons: Senior Secondary", "Preparation and reactions of alkynes",
        "Alkynes form by double dehydrohalogenation and undergo addition reactions; terminal alkynes also show weak acidity.",
